<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { aiApi } from '../services/aiApi'
import { chartRows, toothLabel } from './model'
import { downloadCase, orthodonticCases, type CasePhoto } from './caseModel'
import { arrangeVisibleCrowns, crownBounds, crownTransform, newPhotoStudy, preparePhoto, targetWithinPhoto, validOutline, validateDetection, zeroTarget, type PhotoCrown, type PhotoPoint, type PhotoStudy } from './photoSimulation'
import DentalCareOptions from './DentalCareOptions.vue'
import DentalLocalLearning from './DentalLocalLearning.vue'
import './photoSimulator.css'
const props=defineProps<{photo:CasePhoto;findings:string[];user:{id:number;email:string}|null;authPending:boolean;authError:string}>()
const emit=defineEmits<{authenticate:[email:string,password:string,register:boolean]}>()
const study=computed(()=>props.photo.study??=newPhotoStudy())
const selectedId=ref(''),drawing=ref(false),draft=ref<PhotoPoint[]>([]),draftJaw=ref<PhotoCrown['jaw']>('upper'),pointX=ref(50),pointY=ref(50)
const selected=computed(()=>study.value.crowns.find(c=>c.id===selectedId.value)),reviewedCount=computed(()=>study.value.crowns.filter(c=>c.reviewed).length)
const canPreview=computed(()=>study.value.crowns.length>0&&study.value.crowns.every(c=>c.reviewed))
const prefix='photo-'+crypto.randomUUID(),sourceSvg=ref<SVGSVGElement>(),targetSvg=ref<SVGSVGElement>()
const configured=ref(false),statusChecked=ref(false),pending=ref(false),consent=ref(false),error=ref(''),notice=ref(''),outlines=ref(true)
const showAuth=ref(false),email=ref(''),password=ref(''),register=ref(false),exporting=ref(false)
const localAvailable=ref(false),trainImages=ref(0),validationImages=ref(0),validationDice=ref<number|null>(null)
const modelSource=ref('')
const trainingEpoch=ref(0),trainingEpochs=ref(0),training=ref(false)
let controller:AbortController|undefined,generation=0
let drag:{mode:'vertex'|'target';index:number;id:string;start:PhotoPoint;points:PhotoPoint[];target:PhotoCrown['target']}|null=null
const imageWidth=computed(()=>Math.max(1,Math.round(1000*props.photo.width/props.photo.height))),imageHeight=1000
const targetsFit=computed(()=>study.value.crowns.every(c=>targetWithinPhoto(c,imageWidth.value,imageHeight)))
const allTeeth=chartRows.flat(),topicIds=computed(()=>Array.from(new Set([...(study.value.detection?.possible_case_ids||[]),...props.findings])))
const canArrange=computed(()=>canPreview.value&&study.value.crowns.length>=2&&props.photo.view==='Frontal bite'&&study.value.crowns.every(c=>c.jaw!=='unknown'))
const possibleTopics=computed(()=>orthodonticCases.filter(item=>study.value.detection?.possible_case_ids.includes(item.id)))
function abort(){generation++;controller?.abort();pending.value=false;consent.value=false;error.value=''}
watch(()=>[props.photo.id,props.photo.view,props.user?.id],()=>{abort();drag=null;selectedId.value=study.value.crowns[0]?.id||'';draft.value=[];drawing.value=false;notice.value=''},{immediate:true})
watch(()=>study.value.crowns,()=>{if(pending.value)abort()},{deep:true})
watch(canPreview,value=>{if(!value)study.value.blend=0})
onBeforeUnmount(abort)
async function checkStatus(){try{const value=await aiApi.get<{available:boolean;provider_configured:boolean;runtime:string;state?:string;model_source?:string;train_images?:number;validation_images?:number;validation_dice?:number|null;training_epoch?:number;training_epochs?:number}>('/dental/detector-status');localAvailable.value=value.available&&value.runtime==='local';configured.value=localAvailable.value&&value.provider_configured;modelSource.value=value.model_source||'';trainImages.value=value.train_images||0;validationImages.value=value.validation_images||0;validationDice.value=value.validation_dice??null;training.value=localAvailable.value&&value.state==='training';trainingEpoch.value=value.training_epoch||0;trainingEpochs.value=value.training_epochs||0}catch{configured.value=false;localAvailable.value=false;modelSource.value='';training.value=false}finally{statusChecked.value=true}}
onMounted(checkStatus)
watch(()=>props.user?.id,checkStatus)
function path(points:PhotoPoint[]){return points.map((p,i)=>`${i?'L':'M'}${p.x*imageWidth.value},${p.y*imageHeight}`).join(' ')+' Z'}
function normalized(event:PointerEvent|MouseEvent,svg:SVGSVGElement):PhotoPoint{const bounds=svg.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(event.clientX-bounds.left)/bounds.width)),y:Math.max(0,Math.min(1,(event.clientY-bounds.top)/bounds.height))}}
function selectCrown(id:string){selectedId.value=id;error.value=''}
function startOutline(){drawing.value=true;draft.value=[];error.value='';notice.value='Click 4–12 points around one visible tooth, then finish the outline.'}
function addPoint(x=pointX.value/100,y=pointY.value/100){if(!drawing.value||draft.value.length>=12||!Number.isFinite(x)||!Number.isFinite(y)||x<0||x>1||y<0||y>1)return;draft.value.push({x,y});pointX.value=Math.round(x*1000)/10;pointY.value=Math.round(y*1000)/10}
function sourceClick(event:MouseEvent){if(drawing.value&&sourceSvg.value){const point=normalized(event,sourceSvg.value);addPoint(point.x,point.y)}}
function finishOutline(){
 if(study.value.crowns.length>=32){error.value='Outline up to 32 visible crowns in one photo.';return}
 if(!validOutline(draft.value)){error.value='Use 4–12 ordered points forming a clear, non-crossing crown boundary.';return}
 const crown:PhotoCrown={id:crypto.randomUUID(),jaw:draftJaw.value,points:draft.value.map(p=>({...p})),fdi:null,origin:'manual',reviewed:false,target:zeroTarget()}
 study.value.crowns.push(crown);selectedId.value=crown.id;draft.value=[];drawing.value=false;study.value.blend=0;notice.value='Outline added. Check its boundary and arch, then mark it reviewed.'
}
function changeJaw(value:string){if(!selected.value)return;selected.value.jaw=value as PhotoCrown['jaw'];selected.value.reviewed=false;selected.value.target=zeroTarget()}
function assignFdi(value:string){if(!selected.value)return;const id=value?Number(value):null;if(id&&study.value.crowns.some(c=>c.id!==selected.value!.id&&c.fdi===id)){error.value='This FDI tooth is already assigned to another outline in this photo.';return};selected.value.fdi=id;selected.value.reviewed=false}
function deleteSelected(){if(!selected.value)return;study.value.crowns=study.value.crowns.filter(c=>c.id!==selectedId.value);selectedId.value=study.value.crowns[0]?.id||'';study.value.blend=0}
function startDrag(event:PointerEvent,mode:'vertex'|'target',id:string,index=-1){
 if(drawing.value)return;const crown=study.value.crowns.find(c=>c.id===id),svg=mode==='vertex'?sourceSvg.value:targetSvg.value
 if(!crown||!svg||(mode==='target'&&!canPreview.value))return
 event.preventDefault();event.stopPropagation();selectedId.value=id
 drag={mode,index,id,start:normalized(event,svg),points:crown.points.map(p=>({...p})),target:{...crown.target}}
 if(mode==='target')study.value.blend=1
 svg.setPointerCapture(event.pointerId)
}
function moveDrag(event:PointerEvent){
 if(!drag)return;const crown=study.value.crowns.find(c=>c.id===drag!.id),svg=drag.mode==='vertex'?sourceSvg.value:targetSvg.value;if(!crown||!svg)return
 const p=normalized(event,svg)
 if(drag.mode==='vertex'){crown.points[drag.index]=p;crown.reviewed=false;crown.target=zeroTarget()}
 else{crown.target.dx=Math.max(-.25,Math.min(.25,drag.target.dx+p.x-drag.start.x));crown.target.dy=Math.max(-.25,Math.min(.25,drag.target.dy+p.y-drag.start.y))}
}
function endDrag(event:PointerEvent,cancel=false){if(!drag)return;const crown=study.value.crowns.find(c=>c.id===drag!.id);if(crown&&(cancel||!validOutline(crown.points))){crown.points=drag.points;crown.target=drag.target;error.value=cancel?'':'The boundary crossed itself. The last valid outline was restored.'};const svg=drag.mode==='vertex'?sourceSvg.value:targetSvg.value;if(svg?.hasPointerCapture(event.pointerId))svg.releasePointerCapture(event.pointerId);drag=null}
function changePoint(index:number,axis:'x'|'y',raw:string){if(!selected.value||raw.trim()==='')return;const value=Number(raw)/100;if(!Number.isFinite(value)||value<0||value>1)return;const points=selected.value.points.map(p=>({...p}));points[index]![axis]=value;if(!validOutline(points)){error.value='That change would create an invalid outline.';return};selected.value.points=points;selected.value.reviewed=false;selected.value.target=zeroTarget();error.value=''}
function arrange(){try{const targets=arrangeVisibleCrowns(study.value.crowns);for(const crown of study.value.crowns)crown.target=targets[crown.id]!;study.value.blend=1;notice.value='A simple row arrangement is shown for discussion. It does not calculate a feasible treatment or choose an appliance.';error.value=''}catch(failure){error.value=failure instanceof Error?failure.message:'The arrangement could not be created.'}}
function resetTargets(){for(const crown of study.value.crowns)crown.target=zeroTarget();study.value.blend=0;notice.value='Targets reset to the original photograph.'}
async function detect(assisted=false){
 if(!props.user||!localAvailable.value||(!assisted&&!configured.value)||(assisted&&!selected.value)||!consent.value||pending.value)return
 const selectedCrown=assisted?selected.value:undefined,prompt=selectedCrown?{jaw:selectedCrown.jaw,points:selectedCrown.points.map(p=>({...p}))}:undefined
 const version=++generation;controller?.abort();controller=new AbortController();const signal=controller.signal
 pending.value=true;error.value='';notice.value=''
 try{
  const prepared=await preparePhoto(props.photo.url);if(version!==generation)return
  await aiApi.csrf();if(version!==generation)return
  const result=await aiApi.post<unknown>(assisted?'/dental/segment':'/dental/detect',{photo:{view:props.photo.view,data_url:prepared.data_url},consent_local:true,...(prompt?{prompt}:{})},signal,70000)
  if(version!==generation)return
  const accepted=validateDetection(result,prepared.input_sha256)
  if(accepted.possible_case_ids.length||assisted&&accepted.crowns.length>1)throw new Error('The local tool returned an unsupported result. No outline was changed.')
  if(accepted.image_quality!=='usable'){notice.value=accepted.image_quality==='unsupported_view'?'This image type is unsupported. Use an ordinary dental photograph; no tooth findings were accepted.':'The local model could not return usable tooth outlines for this photo. Try another view or outline the visible crowns manually.';return}
  if(assisted&&selectedCrown){selectedCrown.points=accepted.crowns[0]!.points;selectedCrown.origin='ai-draft';selectedCrown.reviewed=false;selectedCrown.target=zeroTarget();study.value.blend=0;notice.value='Selected outline refined locally using your rough boundary and photo colours. Correct and review it again. This does not train the saved detector.'}
  else{study.value.crowns=accepted.crowns.map(c=>({...c,id:crypto.randomUUID(),fdi:null,origin:'ai-draft',reviewed:false,target:zeroTarget()}));study.value.detection={input_sha256:accepted.input_sha256,image_quality:accepted.image_quality,possible_case_ids:accepted.possible_case_ids};study.value.blend=0;selectedId.value=study.value.crowns[0]?.id||'';notice.value=`${accepted.crowns.length} local draft outlines returned. Crowns can be missed or merged. Correct every outline and assign its arch before moving teeth.`}
 }catch(failure){if(version===generation&&!signal.aborted)error.value=failure instanceof Error?failure.message:'AI detection did not return a valid draft.'}
 finally{if(version===generation){pending.value=false;consent.value=false}}
}
function exportStudy(){downloadCase({schema_version:'humantwin-photo-study-v1',source_photo_sha256:props.photo.sha256,source_dimensions:{width:props.photo.width,height:props.photo.height},photo_view:props.photo.view,image_bytes_included:false,clinical_validation:false,treatment_prediction:false,study:study.value},'humantwin-photo-study.json')}
async function exportComparison(){
 if(!canPreview.value||!targetsFit.value||exporting.value)return;exporting.value=true;error.value=''
 const version=generation,source={url:props.photo.url,sha256:props.photo.sha256},snapshot=JSON.parse(JSON.stringify(study.value)) as PhotoStudy
 try{
  const image=new Image();image.src=source.url;await image.decode();if(version!==generation)return;const scale=Math.min(1,1200/Math.max(image.width,image.height)),w=Math.max(1,Math.round(image.width*scale)),h=Math.max(1,Math.round(image.height*scale)),gap=20,top=42,bottom=82
  const canvas=document.createElement('canvas');canvas.width=w*2+gap;canvas.height=h+top+bottom;const context=canvas.getContext('2d');if(!context)throw new Error('The image export is unavailable.')
  context.fillStyle='#f5f6ef';context.fillRect(0,0,canvas.width,canvas.height);context.fillStyle='#315c53';context.font='bold 16px sans-serif';context.fillText('ORIGINAL PHOTOGRAPH',10,26);context.fillText('ILLUSTRATIVE PHOTO MOCK-UP',w+gap+10,26);context.drawImage(image,0,top,w,h);context.save();context.translate(w+gap,top);context.beginPath();context.rect(0,0,w,h);context.clip();context.drawImage(image,0,0,w,h)
  const trace=(c:PhotoCrown)=>{context.beginPath();c.points.forEach((p,i)=>i?context.lineTo(p.x*w,p.y*h):context.moveTo(p.x*w,p.y*h));context.closePath()}
  if(snapshot.blend>0){for(const crown of snapshot.crowns){trace(crown);context.fillStyle=snapshot.maskColor;context.fill()};for(const crown of snapshot.crowns){const b=crownBounds(crown),k=snapshot.blend;context.save();context.translate(b.cx*w+crown.target.dx*w*k,b.cy*h+crown.target.dy*h*k);context.rotate(crown.target.rotation*k*Math.PI/180);context.translate(-b.cx*w,-b.cy*h);trace(crown);context.clip();context.drawImage(image,0,0,w,h);context.restore()}}
  context.restore();context.fillStyle='#9b5f50';context.font='bold 13px sans-serif';context.fillText('EDUCATIONAL MOCK-UP — NOT A TREATMENT PREDICTION',10,h+top+28);context.fillStyle='#6f7f72';context.font='11px sans-serif';context.fillText('Visible crown pixels repositioned in 2D. Roots, bone, depth and safe tooth movement were not assessed.',10,h+top+49);context.fillText('Source fingerprint: '+source.sha256.slice(0,20)+'…',10,h+top+67)
  const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/png'));if(version!==generation)return;if(!blob)throw new Error('The comparison could not be exported.');const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='humantwin-illustrative-photo-comparison.png';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
 }catch(failure){error.value=failure instanceof Error?failure.message:'The comparison export failed.'}finally{exporting.value=false}
}
</script>
<template>
 <section class="photo-simulator panel" aria-label="Photo-matched dental simulator" data-testid="photo-simulator">
  <div class="photo-sim-heading"><div><span class="dental-eyebrow">YOUR PHOTOGRAPH / YOUR VISIBLE TEETH</span><h3>A simulator that starts with this smile.</h3><p>Outline the actual crowns, check the draft, then explore a visual change.</p></div><span class="photo-sim-badge">Photo-based · 2D</span></div>
  <ol class="photo-sim-steps"><li :class="{done:study.crowns.length}"><span>1</span>Find visible teeth</li><li :class="{done:canPreview}"><span>2</span>Review the outlines</li><li :class="{done:study.blend>0}"><span>3</span>Explore a mock-up</li></ol>
  <div class="photo-detection-bar"><div><strong>{{!statusChecked?'Checking local model…':configured?'Local model trained · review required':training?`Training local detector · ${trainingEpoch} / ${trainingEpochs} epochs`:localAvailable?'Local tools ready · detector not trained yet':'Local dental service is offline'}}</strong><small>Runs on this computer. No external AI provider, API key or automatic photo upload.</small><small v-if="training">Learning from {{trainImages}} public dental images. Check the model again for progress. Automatic detection becomes available after the finished model is exported.</small><small v-else-if="configured&&modelSource==='public-dataset'">Locally trained on {{trainImages}} public dental images; {{validationImages}} validation images. Finds candidate teeth and fits approximate boundaries. Patient-separated evaluation and crown-mask accuracy have not been established.</small><small v-else-if="configured">Trained on {{trainImages}} photos; {{validationImages}} validation photos. Foreground Dice: {{validationDice===null?'unavailable':validationDice.toFixed(3)}}. This is an engineering metric, not proof of medical accuracy.</small></div><button class="button-secondary" @click="checkStatus">Check local model</button><button v-if="!user" class="button-secondary" @click="showAuth=!showAuth">Sign in for local tools</button></div>
  <form v-if="showAuth&&!user" class="photo-auth" @submit.prevent="emit('authenticate',email,password,register)"><label>Email<input v-model="email" type="email" autocomplete="username" required/></label><label>Password<input v-model="password" type="password" :autocomplete="register?'new-password':'current-password'" minlength="12" required/></label><label class="dental-check"><input v-model="register" type="checkbox"/>Create a test account</label><button class="button-primary" :disabled="authPending">{{authPending?'Please wait…':register?'Create account':'Sign in'}}</button><p v-if="authError" role="alert">{{authError}}</p></form>
  <div class="photo-detection-actions"><label class="dental-check"><input v-model="consent" type="checkbox" :disabled="pending"/>I have permission to process this de-identified photograph in the local dental service for this request.</label><div><button class="button-primary" :disabled="!user||!configured||!consent||pending" @click="detect(false)">{{pending?'Processing locally…':study.crowns.length?'Replace outlines with local model draft':'Detect teeth with local model'}}</button><button class="button-secondary" :disabled="!user||!localAvailable||!selected||!consent||pending" @click="detect(true)">Refine selected outline locally</button><button v-if="pending" class="button-secondary" @click="abort">Cancel</button><button class="button-secondary" :disabled="pending" @click="startOutline">Outline a tooth manually</button></div><small>{{configured?'Detect visible teeth, then correct and review every boundary and arch before exploring a visual target.':'Start with a rough manual outline, then refine it locally. Full-photo detection needs a trained model.'}} Requests do not save photos or change the model.</small></div>
  <p v-if="error" class="dental-error" role="alert">{{error}}</p><p v-if="notice" class="photo-sim-notice" role="status">{{notice}}</p>
  <div v-if="possibleTopics.length" class="photo-possible-topics"><span>AI topics for a dentist to check:</span><span v-for="topic in possibleTopics" :key="topic.id">{{topic.name}}</span><small>Tentative discussion topics, not confirmed diagnoses.</small></div>
  <div class="photo-compare-grid"><figure><figcaption><strong>Original & outlines</strong><span>{{reviewedCount}} / {{study.crowns.length}} reviewed</span></figcaption><svg ref="sourceSvg" :viewBox="`0 0 ${imageWidth} ${imageHeight}`" class="photo-source-svg" :class="{'is-drawing':drawing}" aria-label="Original photograph and editable tooth outlines" @click="sourceClick" @pointermove="moveDrag" @pointerup="endDrag($event)" @pointercancel="endDrag($event,true)"><image :href="photo.url" x="0" y="0" :width="imageWidth" :height="imageHeight"/><g v-for="(crown,i) in study.crowns" :key="crown.id" @click.stop="drawing?sourceClick($event):selectCrown(crown.id)"><path :d="path(crown.points)" :class="{'is-selected':selectedId===crown.id,'is-reviewed':crown.reviewed}"/><text :x="crownBounds(crown).cx*imageWidth" :y="crownBounds(crown).cy*imageHeight">{{crown.fdi||`T${i+1}`}}</text><template v-if="selectedId===crown.id&&!drawing"><circle v-for="(point,j) in crown.points" :key="j" :cx="point.x*imageWidth" :cy="point.y*imageHeight" r="10" @pointerdown="startDrag($event,'vertex',crown.id,j)"/></template></g><path v-if="draft.length" class="photo-draft-path" :d="path(draft)"/><circle v-for="(point,j) in draft" :key="`draft-${j}`" :cx="point.x*imageWidth" :cy="point.y*imageHeight" r="8"/></svg></figure>
   <figure><figcaption><strong>{{study.blend===0?'Original position':'Illustrative visual target'}}</strong><span>{{Math.round(study.blend*100)}}% blend</span></figcaption><svg ref="targetSvg" :viewBox="`0 0 ${imageWidth} ${imageHeight}`" class="photo-target-svg" aria-label="Photo-based tooth movement mock-up" @pointermove="moveDrag" @pointerup="endDrag($event)" @pointercancel="endDrag($event,true)"><defs><clipPath v-for="(crown,i) in study.crowns" :id="`${prefix}-${i}`" :key="crown.id"><path :d="path(crown.points)"/></clipPath></defs><image :href="photo.url" x="0" y="0" :width="imageWidth" :height="imageHeight"/><template v-if="canPreview&&study.blend>0"><path v-for="crown in study.crowns" :key="`mask-${crown.id}`" :d="path(crown.points)" :fill="study.maskColor" class="photo-source-mask"/><g v-for="(crown,i) in study.crowns" :key="crown.id" :transform="crownTransform(crown,study.blend,imageWidth,imageHeight)" @pointerdown="startDrag($event,'target',crown.id)"><image :href="photo.url" x="0" y="0" :width="imageWidth" :height="imageHeight" :clip-path="`url(#${prefix}-${i})`"/><path v-if="outlines" :d="path(crown.points)" class="photo-target-outline" :class="{'is-selected':selectedId===crown.id}"/></g></template><text x="20" :y="imageHeight-25" class="photo-watermark">ILLUSTRATIVE MOCK-UP · NOT A TREATMENT PREDICTION</text></svg></figure></div>
  <div v-if="drawing" class="photo-drawing-tools"><strong>Outline one visible crown · {{draft.length}} / 12 points</strong><p>Click around its enamel boundary in the original image. Avoid gums and neighbouring teeth.</p><div><label>Arch<select v-model="draftJaw" aria-label="New outline arch"><option value="upper">Upper</option><option value="lower">Lower</option><option value="unknown">Uncertain</option></select></label><label>X (%)<input v-model.number="pointX" type="number" min="0" max="100" step=".1" aria-label="Outline point X percent"/></label><label>Y (%)<input v-model.number="pointY" type="number" min="0" max="100" step=".1" aria-label="Outline point Y percent"/></label><button class="button-secondary" @click="addPoint()">Add outline point</button><button class="button-secondary" :disabled="!draft.length" @click="draft.pop()">Undo point</button><button class="button-primary" :disabled="draft.length<4" @click="finishOutline">Finish tooth outline</button><button class="dental-text-button" @click="drawing=false;draft=[]">Cancel outline</button></div></div>
  <div v-if="study.crowns.length" class="photo-crown-editor"><div class="photo-crown-list" aria-label="Visible crown selection"><button v-for="(crown,i) in study.crowns" :key="crown.id" :aria-pressed="selectedId===crown.id" @click="selectCrown(crown.id)"><span>{{crown.fdi||`T${i+1}`}}</span><small>{{crown.reviewed?'Reviewed':crown.origin==='ai-draft'?'AI draft':'Manual draft'}}</small></button></div><div v-if="selected" class="photo-crown-details"><div class="photo-crown-meta"><label>Arch<select :value="selected.jaw" aria-label="Selected outline arch" @change="changeJaw(($event.target as HTMLSelectElement).value)"><option value="upper">Upper</option><option value="lower">Lower</option><option value="unknown">Uncertain</option></select></label><label>FDI identity · optional, manual<select :value="selected.fdi??''" aria-label="Manual FDI identity" @change="assignFdi(($event.target as HTMLSelectElement).value)"><option value="">Unassigned</option><option v-for="id in allTeeth" :key="id" :value="id">{{toothLabel(id)}}</option></select></label><button class="dental-text-button photo-delete" @click="deleteSelected">Remove outline</button></div><label class="dental-check photo-outline-review"><input v-model="selected.reviewed" type="checkbox"/>I checked this crown boundary and arch against the photograph.</label><details class="photo-vertex-editor"><summary>Correct boundary coordinates (or drag its points)</summary><div v-for="(point,i) in selected.points" :key="i"><span>Point {{i+1}}</span><label>X %<input :value="Math.round(point.x*10000)/100" type="number" min="0" max="100" step=".1" :aria-label="`Boundary point ${i+1} X percent`" @change="changePoint(i,'x',($event.target as HTMLInputElement).value)"/></label><label>Y %<input :value="Math.round(point.y*10000)/100" type="number" min="0" max="100" step=".1" :aria-label="`Boundary point ${i+1} Y percent`" @change="changePoint(i,'y',($event.target as HTMLInputElement).value)"/></label></div></details><div class="photo-target-controls"><label>Move sideways <output>{{Math.round(selected.target.dx*100)}}% of photo width</output><input v-model.number="selected.target.dx" :disabled="!canPreview" type="range" min="-.25" max=".25" step=".002" aria-label="Photo tooth sideways movement"/></label><label>Move up / down <output>{{Math.round(selected.target.dy*100)}}% of photo height</output><input v-model.number="selected.target.dy" :disabled="!canPreview" type="range" min="-.25" max=".25" step=".002" aria-label="Photo tooth vertical movement"/></label><label>Rotate crown <output>{{selected.target.rotation}}°</output><input v-model.number="selected.target.rotation" :disabled="!canPreview" type="range" min="-45" max="45" step="1" aria-label="Photo tooth rotation"/></label></div><button class="button-secondary" :disabled="!canPreview" @click="study.blend=1">Show this visual target</button></div></div>
  <div class="photo-preview-toolbar"><label class="photo-blend">Original → visual target <output>{{Math.round(study.blend*100)}}%</output><input v-model.number="study.blend" :disabled="!canPreview" type="range" min="0" max="1" step=".02" aria-label="Photo mock-up blend"/></label><div><button class="button-secondary" :disabled="!canArrange" @click="arrange">Sketch an even row</button><button class="dental-text-button" :disabled="!study.crowns.length" @click="resetTargets">Reset targets</button></div><label class="dental-check"><input v-model="outlines" type="checkbox"/>Show target outlines</label><label class="photo-mask-color">Gap fill <input v-model="study.maskColor" type="color" aria-label="Illustrative gap fill color"/></label></div>
  <p v-if="!canPreview" class="photo-review-note">The preview stays at the original position until every outline is reviewed. Start with a manual outline; local refinement can help fit its boundary.</p><p v-else-if="!targetsFit" class="photo-review-note" role="alert">A target crown would leave the photo. Move it back into the frame before exporting a comparison.</p><p class="photo-sim-boundary">This mock-up moves the visible crown pixels from your photo. Exposed gaps use a flat fill, not reconstructed tissue. It does not model roots, bone, hidden teeth, depth, safe movements or treatment timing. A real treatment simulation requires a dental examination and appropriate scan and bite records.</p>
  <div class="photo-export-bar"><button class="button-secondary" :disabled="!study.crowns.length" @click="exportStudy">Export outlines & targets</button><button class="button-primary" :disabled="!canPreview||!targetsFit||exporting" @click="exportComparison">{{exporting?'Preparing comparison…':'Export labeled before / mock-up'}}</button></div>
  <DentalCareOptions :case-ids="topicIds"/>
  <DentalLocalLearning :photo="photo" :study="study" :user="user" :auth-pending="authPending" :auth-error="authError" @authenticate="(email,password,register)=>emit('authenticate',email,password,register)" @model-changed="checkStatus"/>
 </section>
</template>
